const msg = $('WebChat Webhook').first().json.body.message || '';
const msgLower = msg.toLowerCase().trim();

let intent = 'OTRO';
let isTrivial = false;
let staticResponse = '';
let needsHistory = true;

if (/^(hola|buenos d[íi]as|buenas tardes|buenas noches|hey|saludos|q tal)$/.test(msgLower)) {
  intent = 'SALUDO';
  isTrivial = true;
  staticResponse = '¡Hola! 😁 Bienvenido a Smile Studio. ¿En qué te puedo ayudar hoy?';
} else if (/^(gracias|muchas gracias|te lo agradezco|ok|perfecto|vale|entendido)$/.test(msgLower)) {
  intent = 'AGRADECIMIENTO';
  isTrivial = true;
  staticResponse = '¡Con mucho gusto! Aquí estoy si necesitas algo más. 🦷';
} else if (/^(adi[óo]s|bye|hasta luego|nos vemos|chao)$/.test(msgLower)) {
  intent = 'DESPEDIDA';
  isTrivial = true;
  staticResponse = '¡Hasta pronto! Que tengas un excelente día. 😊';
} else if (msgLower.includes('precio') || msgLower.includes('cuesta') || msgLower.includes('costo') || msgLower.includes('pagar') || msgLower.includes('msi') || msgLower.includes('tarjeta')) {
  intent = 'PRECIOS';
} else if (msgLower.includes('horario') || msgLower.includes('ubicacion') || msgLower.includes('dónde están') || msgLower.includes('dirección') || msgLower.includes('abren')) {
  intent = 'HORARIOS_UBICACION';
  needsHistory = false;
} else if (msgLower.includes('cita') || msgLower.includes('agendar') || msgLower.includes('turno')) {
  intent = 'AGENDAR';
}

return { intent, isTrivial, staticResponse, needsHistory, originalMessage: msg };

const intent = $('Intent Classifier').first().json.intent;
const userMessage = $('Intent Classifier').first().json.originalMessage;
const needsHistory = $('Intent Classifier').first().json.needsHistory;

let systemContext = 'Eres Sofía, asistente dental de Smile Studio.';
let knowledgeContext = 'Información general de la clínica dental Smile Studio.';

try {
  const fs = require('fs');
  try { systemContext = fs.readFileSync('/conocimiento/identidad.md', 'utf8'); } catch(e) {}
  try {
    if (intent === 'PRECIOS') knowledgeContext = fs.readFileSync('/conocimiento/servicios_precios.md', 'utf8');
    else if (intent === 'HORARIOS_UBICACION') knowledgeContext = fs.readFileSync('/conocimiento/horarios_ubicacion.md', 'utf8');
    else if (intent === 'AGENDAR') knowledgeContext = fs.readFileSync('/conocimiento/protocolo_agendamiento.md', 'utf8');
    else knowledgeContext = fs.readFileSync('/conocimiento/servicios_precios.md', 'utf8') + '\n\n' + fs.readFileSync('/conocimiento/horarios_ubicacion.md', 'utf8');
  } catch(e) {}
} catch(e) {}

return { systemContext, knowledgeContext, userMessage, needsHistory };

const systemContext = $('Context Builder').first().json.systemContext || '';
const knowledgeContext = $('Context Builder').first().json.knowledgeContext || '';
const needsHistory = $('Context Builder').first().json.needsHistory;
const userMessage = $('Context Builder').first().json.userMessage || '';

let historyText = '';
try {
  if (needsHistory && $('2. Get Recent History')) {
    const historyItems = $('2. Get Recent History').all();
    if (historyItems && historyItems.length > 0) {
      historyText = historyItems.slice().reverse().map(m => {
        const sender = (m.json && m.json.sender_type === 'user') ? 'Paciente' : 'Sofía';
        const text = (m.json && m.json.message_text) ? m.json.message_text : '';
        return sender + ': ' + text;
      }).join('\n');
    }
  }
} catch (e) {}

const systemContent = `====== SISTEMA ======\n${systemContext}\n\n====== CONOCIMIENTO RELEVANTE ======\n${knowledgeContext}`;
const userContent = `${needsHistory && historyText ? '=== HISTORIAL RECIENTE ===\n' + historyText + '\n\n' : ''}Mensaje actual del paciente: "${userMessage}"`;

return {
  messages: [
    { role: 'system', content: systemContent },
    { role: 'user', content: userContent }
  ],
  startTime: Date.now()
};

const startTime = $('Prepare LLM Prompt').first() ? $('Prepare LLM Prompt').first().json.startTime : Date.now();
const telemetry = [];
let finalContent = null;
let winningProvider = null;
let winningModel = null;

// 1. Inspect DeepSeek Primary
try {
  const dsItems = $('1. DeepSeek (LLM Primary)').all();
  if (dsItems && dsItems.length > 0) {
    const dsNode = dsItems[0];
    const dsLatency = Date.now() - startTime;
    if (dsNode && dsNode.json && dsNode.json.choices && dsNode.json.choices[0] && dsNode.json.choices[0].message && dsNode.json.choices[0].message.content) {
      finalContent = dsNode.json.choices[0].message.content;
      winningProvider = 'DeepSeek';
      winningModel = dsNode.json.model || 'deepseek-chat';
      telemetry.push({
        provider: 'DeepSeek',
        model: winningModel,
        httpCode: 200,
        latencyMs: dsLatency,
        error: null,
        usage: dsNode.json.usage || null,
        status: 'SUCCESS'
      });
    } else if (dsNode && dsNode.json) {
      const errObj = dsNode.json.error || null;
      const errMessage = errObj ? (errObj.message || JSON.stringify(errObj)) : 'No content returned';
      const httpCode = dsNode.json.statusCode || (errObj ? (errObj.code || 500) : 500);
      telemetry.push({
        provider: 'DeepSeek',
        model: 'deepseek-chat',
        httpCode: httpCode,
        latencyMs: dsLatency,
        error: errMessage,
        usage: null,
        status: 'FAILED'
      });
    }
  }
} catch (e) {}

// 2. Inspect Gemini Fallback
if (!finalContent) {
  try {
    const gemItems = $('2. Gemini (LLM Fallback)').all();
    if (gemItems && gemItems.length > 0) {
      const gemNode = gemItems[0];
      const gemLatency = Date.now() - startTime;
      if (gemNode && gemNode.json && gemNode.json.choices && gemNode.json.choices[0] && gemNode.json.choices[0].message && gemNode.json.choices[0].message.content) {
        finalContent = gemNode.json.choices[0].message.content;
        winningProvider = 'Gemini';
        winningModel = gemNode.json.model || 'gemini-2.0-flash';
        telemetry.push({
          provider: 'Gemini',
          model: winningModel,
          httpCode: 200,
          latencyMs: gemLatency,
          error: null,
          usage: gemNode.json.usage || null,
          status: 'SUCCESS'
        });
      } else if (gemNode && gemNode.json && gemNode.json.candidates && gemNode.json.candidates[0] && gemNode.json.candidates[0].content && gemNode.json.candidates[0].content.parts) {
        finalContent = gemNode.json.candidates[0].content.parts.map(p => p.text).join('\n');
        winningProvider = 'Gemini';
        winningModel = 'gemini-2.0-flash';
        telemetry.push({
          provider: 'Gemini',
          model: winningModel,
          httpCode: 200,
          latencyMs: gemLatency,
          error: null,
          usage: gemNode.json.usageMetadata || null,
          status: 'SUCCESS'
        });
      } else if (gemNode && gemNode.json) {
        const errObj = gemNode.json.error || null;
        const errMessage = errObj ? (errObj.message || JSON.stringify(errObj)) : 'No content returned';
        const httpCode = gemNode.json.statusCode || (errObj ? (errObj.code || 500) : 500);
        telemetry.push({
          provider: 'Gemini',
          model: 'gemini-2.0-flash',
          httpCode: httpCode,
          latencyMs: gemLatency,
          error: errMessage,
          usage: null,
          status: 'FAILED'
        });
      }
    }
  } catch (e) {}
}

// 3. Inspect OpenRouter Optional
if (!finalContent) {
  try {
    const openItems = $('3. OpenRouter (LLM Optional)').all();
    if (openItems && openItems.length > 0) {
      const openNode = openItems[0];
      const openLatency = Date.now() - startTime;
      if (openNode && openNode.json && openNode.json.choices && openNode.json.choices[0] && openNode.json.choices[0].message && openNode.json.choices[0].message.content) {
        finalContent = openNode.json.choices[0].message.content;
        winningProvider = 'OpenRouter';
        winningModel = openNode.json.model || 'openrouter/free';
        telemetry.push({
          provider: 'OpenRouter',
          model: winningModel,
          httpCode: 200,
          latencyMs: openLatency,
          error: null,
          usage: openNode.json.usage || null,
          status: 'SUCCESS'
        });
      } else if (openNode && openNode.json) {
        const errObj = openNode.json.error || null;
        const errMessage = errObj ? (errObj.message || JSON.stringify(errObj)) : 'No content returned';
        const httpCode = openNode.json.statusCode || (errObj ? (errObj.code || 500) : 500);
        telemetry.push({
          provider: 'OpenRouter',
          model: 'openrouter/free',
          httpCode: httpCode,
          latencyMs: openLatency,
          error: errMessage,
          usage: null,
          status: 'FAILED'
        });
      }
    }
  } catch (e) {}
}

// 4. Controlled Fallback if all failed
if (!finalContent) {
  finalContent = 'En este momento nuestro asistente está experimentando un problema temporal. Por favor intenta nuevamente en unos minutos.';
  winningProvider = 'Fallback';
  winningModel = 'controlled-fallback';
}

return {
  choices: [
    {
      message: {
        role: 'assistant',
        content: finalContent
      }
    }
  ],
  provider: winningProvider,
  model: winningModel,
  telemetry: telemetry
};

const intent = $('Intent Classifier').first().json.intent;
const originalMessage = $('Intent Classifier').first().json.originalMessage;

if (intent === 'AGENDAR') {
  return {
    shouldCreateBooking: true,
    intent: intent,
    originalMessage: originalMessage
  };
} else {
  return {
    shouldCreateBooking: false,
    intent: intent
  };
}

const bookingData = $('Query Booking Details from Chat').first().json;

const dateStr = bookingData.appointment_date_raw || 'lunes 9am';
const parts = dateStr.split(' ');
const dayOfWeek = parts[0] || 'lunes';
const timeStr = parts[1] || '9am';

const dayMap = { 'lunes': 1, 'martes': 2, 'miércoles': 3, 'jueves': 4, 'viernes': 5, 'sábado': 6, 'domingo': 0 };
const dayNum = dayMap[(dayOfWeek || 'lunes').toLowerCase()] !== undefined ? dayMap[(dayOfWeek || 'lunes').toLowerCase()] : 1;
const today = new Date();
const nextDate = new Date();
const daysUntilNext = (dayNum + 7 - today.getDay()) % 7 || 7;
nextDate.setDate(today.getDate() + daysUntilNext);
const hour = parseInt(timeStr) || 9;
nextDate.setHours(hour, 0, 0, 0);

return {
  eventTypeId: 1,
  start: nextDate.toISOString(),
  guests: [bookingData.patient_email || 'noreply@example.com'],
  name: bookingData.patient_name || 'Guest',
  email: bookingData.patient_email || 'noreply@example.com',
  notes: 'Vía Chat Widget - Smile Studio'
};

const req = $('Build Cal.com Booking Request').first().json;
const calRes = $('Create Cal.com Booking').first() ? $('Create Cal.com Booking').first().json : null;

console.log('--- EMAIL CONFIRMATION LOGGED ---');
console.log('Patient Email:', req.email);
console.log('Patient Name:', req.name);
console.log('Appointment Start:', req.start);
console.log('Admin Email:', process.env.ADMIN_EMAIL || 'admin@smilestudio.mx');

return {
  success: true,
  bookingStatus: calRes && calRes.status === 'success' ? 'CONFIRMED' : 'PROCESSED',
  patientEmail: req.email,
  adminEmail: process.env.ADMIN_EMAIL || 'admin@smilestudio.mx'
};
